const $=s=>document.querySelector(s),sleep=ms=>new Promise(resolve=>setTimeout(resolve,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','panels.js','deck-midi.js','midi.js','deck-tap-tempo.js','fx-tempo.js','midi-shift-controls-harness.js'];
const identities=async()=>Object.fromEntries(await Promise.all(files.map(async f=>[f,await hash(await(await fetch(f)).arrayBuffer())])));
async function until(fn,label,ms=12000){const end=performance.now()+ms;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
const click=s=>{assert($(s),'Missing '+s);$(s).click();},field=(s,v)=>{assert($(s),'Missing '+s);$(s).value=String(v);};
const button=(n,a)=>`[data-deck="${n}"][data-action="${a}"]`;
function add(target,ch,n){field('#midi-target',target);field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding','7-bit absolute');click('#midi-add');}
function send(ch,n,value=127){field('#midi-type','Note');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');}
function press(ch,n){send(ch,n);send(ch,n,0);}
function base64(b){let s='';for(let i=0;i<b.length;i+=16384)s+=String.fromCharCode(...b.subarray(i,i+16384));return btoa(s);}
function measure(data,sr,from,to){let power=0;const crossings=[],start=Math.ceil(from*sr),end=Math.floor(to*sr);assert(start>=0&&end<=data.length&&end>start,'Invalid measurement window');for(let i=start;i<end;i++){power+=data[i]**2;if(i>start&&data[i-1]<0&&data[i]>=0)crossings.push((i-1-data[i-1]/(data[i]-data[i-1]))/sr);}return{from,to,rms:Math.sqrt(power/(end-start)),hz:crossings.length>3?(crossings.length-1)/(crossings.at(-1)-crossings[0]):null};}
let app;
async function run(){
 $('#shift-run').disabled=true;const {engine,state}=app,d=state.decks[0],other=state.decks[1];
 const report={startedAt:new Date().toISOString(),completed:false,scope:'Actual app MIDI editor with synthetic messages, Shift transport/tempo actions and complete master recording. No physical/native/full cold/compound/reference acceptance.',criteria:{frequencyErrorHz:.8,playingMinimumRMS:.005,silentMaximumRMS:.0001,tapBPMTolerance:.05},events:[],checks:[],errors:[]};
 const event=name=>{const e={name,time:engine.ctx.currentTime-engine.recordStarted};report.events.push(e);return e;};
 const cc=(ch,n,value)=>{field('#midi-type','CC');field('#midi-channel',ch);field('#midi-number',n);field('#midi-test-value',value);click('#midi-send');};
 const tempo=(ch,msb,lsb=0)=>{cc(ch,8,msb);cc(ch,40,lsb);};
 try{
  report.sourceBefore=await identities();await engine.resume();engine.audioMonitor.mutePhysical(true);await until(()=>engine.audioMonitor.snapshot().physicalMuted,'Physical mute');await until(()=>!state.analysis,'Initial analysis');
  for(let n=0;n<2;n++){const deck=state.decks[n],b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*15,engine.ctx.sampleRate),a=b.getChannelData(n);for(let i=0;i<a.length;i++)a[i]=.12*Math.sin(2*Math.PI*(n?550:(i<engine.ctx.sampleRate?220:440))*i/engine.ctx.sampleRate);Object.assign(deck.track,{bpm:120,grid:0,gridWarpMarkers:[],duration:15,analyzed:true,sampleGain:0,locked:false});Object.assign(deck,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,stemSlip:'off',slip:false,sync:false,level:n?.8:0,cue:0});engine.clearDeckScratchCache(n);engine.buffers.set(deck.track.id,b);engine.mix(n,'level',deck.level);}
  await engine.seek(d,1);click('[data-panel="midi"]');click('#midi-reset');
  for(const [target,ch,n,type,encoding]of [['Deck 1 fader start',5,0,'CC','7-bit absolute'],['Deck 2 tempo',3,8,'CC','14-bit absolute'],['Deck 2 tempo ignore',6,8,'CC','14-bit absolute'],['Deck 2 tap tempo',6,12,'Note','7-bit absolute']]){field('#midi-target',target);field('#midi-type',type);field('#midi-channel',ch);field('#midi-number',n);field('#midi-encoding',encoding);click('#midi-add');}
  cc(5,0,0);await until(()=>d.cue===1,'Paused bottom fader sets temp cue');click('#modal-close');click(button(1,'play'));await until(()=>other.playing,'Background deck Play');click('[data-panel="midi"]');await engine.recordStart();
  cc(5,0,100);cc(5,0,0);await sleep(140);assert(!d.playing&&!d.processing&&!engine.voices.has(0),'Early bottom fader allowed late playback');report.cancelledStart={playing:d.playing,processing:d.processing,hasVoice:engine.voices.has(0)};const cancelled=event('cancelled-start-silent');await sleep(240);
  cc(5,0,100);await until(()=>d.playing&&!d.processing,'Fader start from temp cue');report.faderStart={cue:d.cue,position:engine.position(d),level:d.level};assert(engine.position(d)>=1&&engine.position(d)<1.1,'Fader start did not use temporary cue');const playing=event('fader-start-playing');await sleep(280);cc(5,0,0);await until(()=>!d.playing&&!d.processing&&engine.position(d)===1,'Fader back-cue');report.backCue={playing:d.playing,position:engine.position(d)};const backCue=event('fader-back-cue-silent');await sleep(240);
  tempo(3,64);await until(()=>other.rate===1,'Initial tempo pickup');tempo(6,96);tempo(3,96);await until(()=>$('#notice').textContent.includes('pick it up'),'Normal tempo still waiting for pickup');assert(other.rate===1,'Ignored motion changed audible tempo');report.ignored={rate:other.rate,notice:$('#notice').textContent};const ignored=event('ignored-tempo-stable');await sleep(240);tempo(3,64);tempo(3,80);await until(()=>other.rate>1.019&&other.rate<1.021,'Pickup and positive tempo movement');report.pickedUp={rate:other.rate};const pitched=event('picked-up-tempo');await sleep(240);
  press(6,12);await sleep(400);press(6,12);await until(()=>other.track.metadataSources?.bpm==='manual','Tapped BPM write');await sleep(800);press(6,12);await sleep(30);
  const stamps=state.midiLog.filter(s=>s.includes('Note ch6 12=127')).map(s=>Number(/· ([\d.]+)ms/.exec(s)[1])),first=stamps[1]-stamps[0],second=(stamps[2]-stamps[1])/2,expected=Math.round(60000/((first+second)/2)/other.rate*100)/100;
  report.tap={timestamps:stamps,expectedSourceBPM:expected,sourceBPM:other.track.bpm,rate:other.rate,pfl:!!other.pfl,metadataSource:other.track.metadataSources.bpm};assert(Math.abs(other.track.bpm-expected)<.05,'Tapped BPM did not compensate audible rate/octave interval');assert(!other.pfl,'Shift Tap changed headphone selection');const tapped=event('tap-updated-metadata-same-audio');await sleep(250);
  const beforeLocked=other.track.bpm;other.track.locked=true;press(6,12);await until(()=>$('#notice').textContent.includes('Beatgrid locked'),'Locked Tap refusal');assert(other.track.bpm===beforeLocked,'Locked grid BPM changed');other.track.locked=false;report.lockedTapPreserved=true;assert(JSON.parse(localStorage.getItem('openplay-review-v1')).tags[other.track.id].bpm===beforeLocked,'Tapped BPM did not persist');click('#modal-close');
  const blob=await engine.recordStop(),bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};const decoded=await engine.ctx.decodeAudioData(bytes.buffer.slice(0));report.decoded={duration:decoded.duration,sampleRate:decoded.sampleRate,frames:decoded.length,channels:decoded.numberOfChannels};assert(decoded.numberOfChannels===2,'Expected stereo');for(let c=0;c<2;c++)for(const v of decoded.getChannelData(c))assert(Number.isFinite(v),'Nonfinite PCM');
  report.audio=[['cancelled',cancelled,[null,550]],['fader-start',playing,[440,550]],['back-cue',backCue,[null,550]],['ignored',ignored,[null,550]],['pickup',pitched,[null,550*report.pickedUp.rate]],['tap',tapped,[null,550*report.pickedUp.rate]]].map(([name,e,expected])=>({name,expected,channels:[0,1].map(c=>measure(decoded.getChannelData(c),decoded.sampleRate,e.time+.06,e.time+.19))}));for(const w of report.audio)w.channels.forEach((m,c)=>{if(w.expected[c]===null)assert(m.rms<.0001,w.name+' expected silence');else assert(m.rms>.005&&Math.abs(m.hz-w.expected[c])<.8,w.name+' expected carrier');});
  report.checks=['Early fader return cancels without late playback; raise plays temp cue and bottom back-cues','Ignored paired14bit motion keeps tempo, normal fader requires pickup before actual pitch change','Tap BPM compensates actual rate/octave cadence, persists metadata without PFL or audio-rate change','Locked-grid Tap refuses changes; whole master recording matches declared phases'];
 }catch(error){report.errors.push({message:error.message,stack:error.stack});}
 finally{
  for(const deck of state.decks)engine.pause(deck);if(engine.recording){const blob=await engine.recordStop();if(blob){const bytes=new Uint8Array(await blob.arrayBuffer());report.recording={bytes:bytes.length,format:blob.type,sha256:await hash(bytes),base64:base64(bytes)};}}report.sourceAfter=await identities();report.sourceStable=JSON.stringify(report.sourceBefore)===JSON.stringify(report.sourceAfter);report.completed=report.checks.length===4&&!report.errors.length&&report.sourceStable;report.finishedAt=new Date().toISOString();$('#shift-original').textContent=JSON.stringify(report,null,2);$('#shift-results').textContent=JSON.stringify({...report,recording:report.recording?{...report.recording,base64:'Retained in original JSON'}:null},null,2);$('#shift-status').textContent=report.completed?'Scoped Shift-controls workflow passed; audio stopped':'Failed: '+report.errors.map(e=>e.message).join('; ');
 }
}
$('#shift-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[1].track,'Actual app');app=window.openPlay;$('#shift-run').disabled=false;$('#shift-run').textContent='Run one Shift-controls workflow';}
boot().catch(error=>$('#shift-status').textContent=error.message);
